/**
 * What the 3D story showed besides its chapter and part cards, kept here word
 * for word (origin/master 1768581f): the part labels and their hover notes
 * (home3d/story.js HOVER, HOVER_WHAT, HOVER_ROBOT), the scrolling ribbons that
 * listed every design in a line, and the large word over each chapter
 * (Home.tsx, the kinetic layer). Chapters.tsx shows them in each chapter. A
 * design line is left out where the chapter already says it.
 * Generated by www-redesign/work/port/tools/gen-extras.cjs.
 */
export type Status = "code" | "part" | "docs" | "none";

/** The legend's own words for each status. */
export const STATUS_LABEL: Record<Status, string> = {
  code: "Working",
  part: "In code",
  docs: "Docs or descriptor",
  none: "Not in the repos yet",
};

export interface ChapterExtra {
  /** the large word the 3D story set over the chapter */
  word?: string;
  /** the design, and what it is (from its hover card) */
  design?: [string, string];
  /** part label ("" for the device as a whole), what EoS does with it, status */
  notes?: [string, string, Status][];
  /** the robot's parts: name, spec, what EoS does with it, status */
  robot?: [string, string, string, Status][];
  /** every design in the line, as the ribbon listed it */
  line?: { head: string; items: [string, Status][] };
}

